    "What happens at graduation?": "졸업하면 어떻게 되나요?",
    "When the real USDC in the curve reaches its graduation threshold, trading moves from the curve to a DEX pool with that liquidity. The progress above is read live from the curve.": "커브의 실제 USDC가 졸업 기준에 도달하면, 그 유동성으로 거래가 커브에서 DEX 풀로 옮겨 갑니다. 위 진행률은 커브에서 실시간으로 읽어 옵니다.",
