    "Unlocked on": "해제일",
    "all locks": "전체 잠금",
    "Extending only ever moves the date later. An unlocked lock that you extend is locked again from today.": "연장은 날짜를 뒤로만 미룹니다. 이미 풀린 잠금을 연장하면 오늘부터 다시 잠깁니다.",
    "Pick a date": "날짜 선택",
