    "Scanner": "스캐너",
    "Utility · On-chain check": "유틸리티 · 온체인 점검",
    "Updated regularly": "계속 업데이트",
    "Version 1 — new checks are added regularly": "버전 1 — 새로운 점검 항목이 계속 추가됩니다",
    "Paste any Arc token. The scanner reads its contract, who can still change it, where it trades and who holds it — then sums it up in one score. It reads the chain; it can't promise a token is safe.": "Arc 토큰 주소를 붙여넣으세요. 스캐너가 컨트랙트, 아직 바꿀 수 있는 사람, 거래되는 곳, 보유자를 읽고 하나의 점수로 정리합니다. 체인을 읽을 뿐, 토큰이 안전하다고 보장하지는 않습니다.",
    "Paste": "붙여넣기",
    "Scan": "스캔",
    "What it checks": "점검 항목",
    "Contract": "컨트랙트",
    "Control": "권한",
    "Market": "마켓",
    "Is it a standard token? Can its code be swapped out (proxy)? Was it launched on ArcPad?": "표준 토큰인가요? 코드를 바꿀 수 있나요(프록시)? ArcPad에서 런치했나요?",
    "Who owns it — and can they still mint, pause, block wallets or change fees?": "누가 소유하고 있고, 아직 발행·정지·지갑 차단·수수료 변경이 가능한가요?",
    "Where it trades, how deep the pool is, how old it is, and whether people can actually sell.": "어디서 거래되는지, 풀이 얼마나 깊은지, 얼마나 오래됐는지, 실제로 팔 수 있는지.",
    "How spread out the supply is, leaving out the pool, burned and locked tokens.": "풀·소각·잠금 물량을 뺀 공급량이 얼마나 분산돼 있는지.",
    "Coming next": "다음 업데이트",
    "Buy and sell simulation — the real tax, and whether selling works": "매수·매도 시뮬레이션 — 실제 세금과 매도 가능 여부",
    "Verified source code check": "소스 코드 검증 여부 확인",
    "Deployer history — their other tokens": "배포자 이력 — 그들이 만든 다른 토큰",
    "Shareable scan cards for X": "X에 공유할 수 있는 스캔 카드",
    "Reads Arc directly, plus Dexscreener for market data. An automated check, not advice — a clean scan can't rule out every risk, and a warning doesn't always mean a scam.": "Arc를 직접 읽고, 시장 데이터는 Dexscreener를 사용합니다. 자동 점검일 뿐 투자 조언이 아닙니다 — 깨끗한 결과가 모든 위험을 배제하지는 않고, 경고가 곧 사기를 뜻하지도 않습니다.",
    "Reading the contract": "컨트랙트 읽는 중",
