    "See the results": "결과 보기",
    "Candidates go up during the raise. Voting opens the moment it closes and runs for 48 hours.": "모금 기간에 후보가 올라와요. 모금이 마감되는 순간 투표가 열리고 48시간 동안 진행돼요.",
    "Voting is open. Every contributor has a say, weighted by the USDC they put in.": "투표가 열렸어요. 모든 참여자가 넣은 USDC만큼의 비중으로 투표해요.",
    "Voting has closed — these results are final.": "투표가 마감됐어요 — 이 결과가 최종이에요.",
