    "The vote contract for this round is being set up. Candidates will appear here, and voting opens the moment the raise closes.": "이번 라운드의 투표 컨트랙트를 준비 중이에요. 후보가 여기에 올라오고, 모금이 마감되는 순간 투표가 열려요.",
    "Voting opens the moment the raise closes and runs for 48 hours. Your weight is the USDC you put in, locked in at the close.": "모금이 마감되는 순간 투표가 열리고 48시간 동안 진행돼요. 투표 비중은 내가 넣은 USDC이고, 마감 시점에 고정돼요.",
