    "Scan this token": "이 토큰 스캔",
    "Share of the liquidity trading at the current price": "현재 가격에서 거래되는 유동성 기준 비중",
    "The first look at a token reads every position on Arc — later visits are instant.": "토큰을 처음 볼 때는 Arc의 모든 포지션을 읽어요 — 다음부터는 바로 떠요.",
    "This pool's LP fee is 0% — ArcPad's hook takes the trading fee, so liquidity added here earns nothing.": "이 풀의 LP 수수료는 0%예요 — 거래 수수료는 ArcPad 훅이 가져가서, 여기에 넣은 유동성은 수익이 없어요.",
