    "This pool runs a hook contract ARCIRCLE PAD doesn't recognise. A hook can change swaps, fees or withdrawals — only add liquidity if you trust it.": "이 풀은 ARCIRCLE PAD가 모르는 훅 컨트랙트를 사용합니다. 훅은 스왑·수수료·출금을 바꿀 수 있으니 신뢰할 때만 유동성을 넣으세요.",
