    "$ARCIRCLE burned to decide it": "이 결과를 위해 소각된 $ARCIRCLE",
    "$ARCIRCLE buybacks and promotion": "$ARCIRCLE 바이백과 홍보",
    "48 hours. Anyone holding $ARCIRCLE votes on name, ticker, logo, roadmap and launch date; every vote burns 1,000 $ARCIRCLE.": "48시간. $ARCIRCLE 보유자라면 누구나 이름, 티커, 로고, 로드맵, 런치 날짜에 투표하고, 1표마다 $ARCIRCLE 1,000개가 소각됩니다.",
    "Burn-to-vote": "소각 투표",
