    "No votes yet — the first burn shows up here.": "아직 투표가 없어요 — 첫 소각이 여기에 표시돼요.",
    "Not decided yet": "아직 미정",
    "On the launch date the vote picks, with the name, ticker and logo the vote picks. Where and how it launches: not decided yet.": "투표로 정한 날짜에, 투표로 정한 이름·티커·로고로 런치합니다. 어디서 어떻게 런치할지: 아직 미정.",
    "Paid to the top contributor over 3 days": "최대 참여자에게 3일에 걸쳐 지급",
