    "The date the vote picks": "투표로 정한 날짜",
    "The largest contributor at the close receives the 15%, over 3 days, sent by the team from the treasury wallet.": "마감 시점 최대 참여자가 15%를 3일에 걸쳐 받습니다. 팀이 트레저리 지갑에서 보냅니다.",
    "The project's funds": "프로젝트 자금",
    "The raise closes": "모금 마감",
    "The split is shown here once the round opens.": "라운드가 열리면 분배가 여기에 표시돼요.",
    "This is the coin the circle chose.": "서클이 고른 코인입니다.",
    "Top burners": "최다 소각자",
    "Top contributor at the close": "마감 시 최대 참여자",
