    "One $ARCIRCLE on three chains. Sending it from Arc locks it here and mints the same amount on the other chain; sending it back burns it there and unlocks it on Arc. The global supply stays 1,000,000,000.": "세 체인에서 하나의 $ARCIRCLE. Arc에서 보내면 여기서 잠기고 상대 체인에서 같은 양이 발행돼요. 되돌려 보내면 그쪽에서 소각되고 Arc에서 잠금이 풀려요. 전체 공급량은 언제나 1,000,000,000이에요.",
