    "You're in the next relay": "다음 릴레이 대상이에요",
    "{n} more $ARCIRCLE to join the next relay (locked tokens count)": "$ARCIRCLE {n}개 더 있으면 다음 릴레이 대상 (락한 토큰도 인정)",
    "Locks, LP positions and Relay Launch are read from Arc for your connected wallet. Scans, snapshots, sends and bridge transfers are the ones made in this browser.": "락, LP 포지션, 릴레이 런치는 연결된 지갑 기준으로 Arc에서 읽어요. 스캔, 스냅샷, 전송, 브리지 기록은 이 브라우저에서 한 것만 보여요.",
    "Right now": "지금 상태",
    "How do I take a holder snapshot on ARCIRCLE PAD and turn it into an airdrop?": "ARCIRCLE PAD에서 홀더 스냅샷을 찍고 에어드랍으로 만드는 방법은?",
    "How do I read a pool in the ARCIRCLE PAD Liquidity Manager — fee yield, range and locked liquidity?": "ARCIRCLE PAD 유동성 매니저에서 풀을 읽는 법 — 수수료 수익률, 범위, 락된 유동성은?",
    "How does Relay Launch work, and how do I get into the next relay?": "릴레이 런치는 어떻게 작동하고, 다음 릴레이에 들어가려면 어떻게 해야 해?",
    "{n} holders": "홀더 {n}명",
    "{n} locked": "{n}개 락",
    "Launch platform": "런칭 플랫폼",
    "ArcPad pool · 1 USDC fee · your own add-on fee": "ArcPad 풀 · 수수료 1 USDC · 내 추가 수수료",
    "Argus Portal #8 · buy / sell tax · 70% of creator fees to you": "Argus Portal #8 · 매수/매도 세금 · 크리에이터 수수료의 70%가 내 몫",
    "Launched on Argus, from your own wallet": "내 지갑에서 Argus로 런칭",
    "Your coin goes live on Argus Portal #8 with a Uniswap v4 pool and fixed buy / sell taxes, paid in USDC. Argus takes its own share of every fee as usual. Of the creator share, 70% is yours and 30% goes to the ARCIRCLE PAD treasury — set on-chain with Argus's own fee split.": "코인은 Uniswap v4 풀과 고정된 매수/매도 세금(USDC로 지급)과 함께 Argus Portal #8에 상장돼요. Argus는 평소처럼 모든 수수료에서 자기 몫을 가져가요. 크리에이터 몫 중 70%는 내 것, 30%는 ARCIRCLE PAD 트레저리로 가요 — Argus 자체의 수수료 분배 기능으로 온체인에 설정돼요.",
    "taken on every trade, fixed forever": "모든 거래에 부과, 영구 고정",
    "Buy tax": "매수 세금",
    "Sell tax": "매도 세금",
    "Each side 0–10%, and not both 0. Argus fixes them at launch — nobody can change them later.": "각각 0–10%, 둘 다 0은 안 돼요. Argus가 런칭 때 고정해서 이후엔 아무도 바꿀 수 없어요.",
    "your four shares, after Argus's cut": "Argus 몫을 뺀 뒤 네 가지 배분",
    "Opening buy": "오프닝 매수",
    "Argus requires one — your first tokens, bought in the launch transaction": "Argus 필수 항목 — 런칭 트랜잭션에서 사는 첫 토큰",
    "Minimum buy": "최소 매수",
    "Reading Argus's minimum…": "Argus 최소 금액 읽는 중…",
    "ArcPad support for coins launched here": "여기서 런칭한 코인에 대한 ArcPad 지원",
    "At a $20K market cap we help update the coin's Dexscreener info — logo, links and description.": "시가총액 $20K 달성 시 코인의 Dexscreener 정보(로고, 링크, 설명) 업데이트를 지원해요.",
    "At a $100K market cap we add marketing support, decided case by case — boosts, calls and promotion.": "시가총액 $100K 달성 시 상황에 따라 마케팅을 지원해요 — 부스트, 콜, 홍보 활동.",
    "Support may be refused if our Token Scanner finds signs of manipulation — snipers, bundled buys, wash trading or similar — or if the 70 / 30 fee split is removed.": "Token Scanner에서 조작 정황(스나이퍼, 번들 매수, 자전거래 등)이 확인되거나 70 / 30 수수료 분배가 해제되면 지원이 불가할 수 있어요.",
    "This is ARCIRCLE PAD's own support policy, not a contract, and it can change. The coin's fees and taxes are Argus's and follow Argus's rules.": "이는 컨트랙트가 아닌 ARCIRCLE PAD 자체 지원 정책이며 변경될 수 있어요. 코인의 수수료와 세금은 Argus의 것이며 Argus의 규칙을 따라요.",
    "I understand: two signatures (the launch, then the 70 / 30 fee split), taxes fixed forever, and support as described above.": "이해했어요: 서명 두 번(런칭, 그다음 70 / 30 수수료 분배), 세금은 영구 고정, 지원은 위 설명대로예요.",
    "70% of fees to you": "수수료 70%는 내 몫",
    "Your coin goes live on Argus the moment the launch confirms; the fee split is the second signature.": "런칭이 확정되는 순간 코인이 Argus에 상장되고, 수수료 분배는 두 번째 서명이에요.",
    "Launch on Argus via ArcPad": "ArcPad를 통해 Argus에서 런치",
    "Paid to the creator — 70% to you, 30% to ARCIRCLE PAD": "크리에이터에게 지급 — 70% 나, 30% ARCIRCLE PAD",
    "Buys the coin back and burns it": "코인을 다시 사서 소각해요",
    "Holder dividends": "홀더 배당",
    "Paid out to holders in USDC": "홀더에게 USDC로 지급",
    "Added to the pool": "풀에 추가돼요",
    "Adds up to 100%": "합계 100%",
    "Adds up to": "합계",
    "it must be exactly 100%.": "정확히 100%여야 해요.",
    "Fix it": "맞추기",
    "The creator share must be at least 50%.": "크리에이터 몫은 최소 50%여야 해요.",
    "To you": "나에게",
    "Of every $100 of tax collected": "걷힌 세금 $100마다",
    "Argus's share is read live from the Portal. Creator fees wait on Argus until claimed — you and ARCIRCLE PAD each claim your own part at argus.world/claim.": "Argus 몫은 Portal에서 실시간으로 읽어요. 크리에이터 수수료는 청구할 때까지 Argus에 쌓여요 — 나와 ARCIRCLE PAD가 각자 argus.world/claim에서 자기 몫을 받아요.",
    "Argus's minimum is {n} USDC. More buys you more of your coin at the opening price; Argus refuses an opening buy that would reach its bonding mark.": "Argus 최소 금액은 {n} USDC예요. 더 넣으면 오프닝 가격에 코인을 더 많이 사요. 본딩 지점에 닿을 만큼 큰 오프닝 매수는 Argus가 거부해요.",
