    "Ranks & badges": "등급 & 배지",
    "Lifetime points across every mine. Each rank adds a bonus and unlocks characters and pets.": "모든 광산의 누적 포인트 기준입니다. 등급마다 보너스가 붙고 캐릭터와 펫이 열립니다.",
