    "Opening a mine and joining one each cost 1 USDC worth of $ARCIRCLE — burned, never paid to anyone.": "광산 개설과 참여는 각각 1 USDC어치 $ARCIRCLE이 들고, 전부 소각됩니다 — 누구에게도 지급되지 않아요.",
