    "Price and volume per hour from the pool's own swaps on Arc, with events marked.": "Arc 풀의 스왑으로 만든 시간당 가격·거래량, 이벤트 표시 포함.",
    "Price moves up": "가격 상승폭",
    "Price per hour and volume": "시간당 가격과 거래량",
    "Pro's free daily unlock needs one public post of a scan from your X account. The link carries your wallet, so the post counts for you.": "Pro의 하루 무료 열기는 내 X 계정에서 스캔을 공개로 한 번 올려야 합니다. 링크에 내 지갑이 들어 있어 내 게시물로 인정됩니다.",
    "Pro: post one scan on X today": "Pro: 오늘 X에 스캔 하나 올리기",
