    "Proxy that can't be repointed": "바꿀 수 없는 프록시",
    "Published (verified) source code lets anyone read what the contract does. Unpublished code can hide tricks the scanner can't see.": "공개(검증)된 소스 코드는 누구나 컨트랙트가 하는 일을 읽을 수 있게 합니다. 공개되지 않은 코드는 스캐너가 볼 수 없는 수법을 숨길 수 있습니다.",
    "Reading the wallet's history…": "지갑 기록을 읽는 중…",
    "Report saved — link copied.": "리포트 저장 — 링크를 복사했습니다.",
    "Report saved.": "리포트를 저장했습니다.",
    "Revoking…": "취소하는 중…",
    "Same code as a flagged token": "플래그된 토큰과 같은 코드",
    "Same result at every size": "모든 크기에서 같은 결과",
    "Save rules": "규칙 저장",
    "Scammers copy the ticker of a known token. Check you have the right contract address before you buy.": "사기꾼은 유명 토큰의 티커를 베낍니다. 사기 전에 컨트랙트 주소가 맞는지 확인하세요.",
    "Scan them": "스캔하기",
    "Scanning soon": "곧 스캔",
    "Score {x}": "점수 {x}",
    "Search by name": "이름으로 검색",
    "Search tokens by name or ticker": "이름이나 티커로 토큰 검색",
    "Self-destruct and delegatecall let a contract remove itself or run code from somewhere else — both can change what the token does after you buy.": "셀프디스트럭트와 delegatecall은 컨트랙트가 스스로를 지우거나 다른 곳의 코드를 실행하게 합니다 — 둘 다 산 뒤에 토큰의 동작을 바꿀 수 있습니다.",
    "Sell straight back": "바로 되팔면",
    "Selling failed in a dry run.": "모의 실행에서 매도가 실패했습니다.",
    "Several people must sign before any owner-only function runs.": "소유자 전용 기능이 실행되려면 여러 명이 서명해야 합니다.",
    "Several tokens share this ticker — pick by the address, not the name.": "여러 토큰이 이 티커를 씁니다 — 이름이 아니라 주소로 고르세요.",
    "Show on the map": "지도에서 보기",
    "Sign and post": "서명하고 올리기",
    "Sign in and post one scan on X a day: 1 free unlock a day, then 2,000 $ARCIRCLE burned per unlock.": "로그인하고 하루 한 번 X에 스캔을 올리면: 하루 1회 무료, 그 뒤로는 열 때마다 2,000 $ARCIRCLE 소각.",
    "Sign in for Plus & Pro": "Plus·Pro 로그인",
    "Sign in with a wallet. 3 free unlocks a day per wallet, then 1,000 $ARCIRCLE burned per unlock.": "지갑으로 로그인. 지갑당 하루 3회 무료, 그 뒤로는 열 때마다 1,000 $ARCIRCLE 소각.",
    "Sign in with your wallet to use it.": "지갑으로 로그인하면 쓸 수 있습니다.",
    "Sign out": "로그아웃",
    "Signed by the": "서명:",
    "Since the last scan of this token.": "이 토큰의 지난 스캔 이후.",
    "Sizes are shares of the supply. A pretend transfer on the latest block — nothing is signed or spent.": "크기는 공급량 대비 비율입니다. 최신 블록에서 가짜로 전송해 본 것이며 서명하거나 쓰는 것은 없습니다.",
    "Smaller ones — still, check the contract address before you buy.": "더 작은 것들입니다 — 그래도 사기 전에 컨트랙트 주소를 확인하세요.",
    "Snipers are bots or insiders that buy in the first seconds a pool opens, before anyone else can. If they still hold a big share, they can dump on later buyers.": "스나이퍼는 풀이 열린 첫 몇 초 안에 누구보다 먼저 사는 봇이나 내부자입니다. 아직 많이 들고 있다면 나중 매수자에게 던질 수 있습니다.",
    "Some tokens keep a second admin (admin, operator, governance…) that still works after owner() is renounced.": "일부 토큰은 owner()를 포기한 뒤에도 작동하는 두 번째 관리자(admin, operator, governance…)를 남겨 둡니다.",
    "Some wallets look linked": "일부 지갑이 연결되어 보임",
    "Someone still holds keys that can mint, pause or block wallets.": "누군가 아직 발행·정지·지갑 차단 권한을 쥐고 있습니다.",
    "Source code not published": "소스 코드 미공개",
    "Source code published": "소스 코드 공개됨",
    "Stress test": "스트레스 테스트",
    "Switch your wallet back to the one you signed in with.": "로그인한 지갑으로 다시 바꾸세요.",
    "Tax grows with trade size": "거래가 클수록 세금이 커짐",
    "That isn't a token address.": "토큰 주소가 아닙니다.",
    "The 3 busiest wallets": "가장 활발한 지갑 3개",
    "The biggest linked group sells": "가장 큰 연결 그룹이 팔면",
    "The deployer sells what it holds": "배포자가 보유분을 팔면",
    "The dry run buys from the pool into a brand-new wallet, then sells from it. If that sell fails while older holders can sell, only a chosen few can get out.": "모의 실행은 풀에서 새 지갑으로 산 뒤 그 지갑에서 팝니다. 기존 보유자는 팔 수 있는데 이 매도가 실패하면, 선택된 소수만 빠져나갈 수 있다는 뜻입니다.",
    "The dry run sells about 0.01%, 0.1% and 1% of the supply. A tax that grows with size, or a bigger sell that's refused, only hurts larger holders.": "모의 실행은 공급량의 약 0.01%, 0.1%, 1%를 팝니다. 크기에 따라 커지는 세금이나 거부되는 큰 매도는 큰 보유자에게만 피해를 줍니다.",
    "The largest wallet sells everything": "가장 큰 지갑이 전부 팔면",
    "The latest trades with the pool: how many wallets, and who makes most of them.": "풀과의 최근 거래: 몇 개의 지갑이, 누가 대부분을 하는지.",
    "The launch snipers sell": "출시 스나이퍼가 팔면",
    "The owner changes or renounces": "소유자가 바뀌거나 포기할 때",
    "The project hasn't posted a note.": "프로젝트가 올린 메모가 없습니다.",
    "The project's own words — not checked by ARCIRCLE.": "프로젝트 자신의 말입니다 — ARCIRCLE이 확인한 내용이 아닙니다.",
    "The result in plain words, and the one thing to check before buying.": "결과를 쉬운 말로, 그리고 사기 전에 확인할 한 가지.",
    "The scanner couldn't read this part right now. It isn't counted as good or bad — try the scan again.": "스캐너가 지금 이 부분을 읽지 못했습니다. 좋거나 나쁘게 계산하지 않습니다 — 다시 스캔해 보세요.",
    "The scanner score drops 10 or more": "스캐너 점수가 10 이상 떨어질 때",
    "The tokens go to the dead address — nobody receives them.": "토큰은 소각 주소로 갑니다 — 아무도 받지 않습니다.",
    "The top 10 wallets hold {x}.": "상위 10개 지갑이 {x}를 보유합니다.",
    "The top 10 wallets sell everything": "상위 10개 지갑이 전부 팔면",
    "Then paste the link to your post": "그다음 게시물 링크를 붙여넣으세요",
