    "Wallets that passed tokens between each other, got them from the same sender, or bought in the same first block are probably one owner — together they hold more than any one of them shows.": "서로 토큰을 주고받았거나, 같은 보낸이에게 받았거나, 같은 첫 블록에 산 지갑들은 아마 한 사람입니다 — 합치면 각각 보이는 것보다 많이 갖고 있습니다.",
    "Webhook added": "웹훅을 추가했습니다",
    "What a buy would get you, how far it moves the price, and what selling straight back would return.": "샀을 때 얼마를 받는지, 가격이 얼마나 움직이는지, 바로 되팔면 얼마가 돌아오는지.",
    "What changed": "바뀐 점",
    "What else the wallet that created this token has made. A creator whose other tokens scored high risk is a warning sign.": "이 토큰을 만든 지갑이 그 밖에 무엇을 만들었는지. 다른 토큰이 고위험 점수를 받은 생성자는 경고 신호입니다.",
    "What the price would do if the biggest holders sold everything.": "가장 큰 보유자들이 전부 팔면 가격이 어떻게 될지.",
    "When many different wallets buy in the exact same first block, it is usually one person splitting a buy to look like many holders.": "서로 다른 많은 지갑이 정확히 같은 첫 블록에 샀다면, 대개 한 사람이 매수를 나눠 여러 보유자처럼 보이게 한 것입니다.",
    "Where the points went": "점수가 깎인 곳",
