    "Argus launch share": "Argus 런칭 몫",
    "30% of the creator share on coins launched on Argus through ArcPad": "ArcPad를 통해 Argus에 런칭한 코인의 크리에이터 몫 중 30%",
    "Paid tools and ARCIA 402; Token Scanner unlocks and Builder Mine burn $ARCIRCLE directly": "유료 툴과 ARCIA 402; 토큰 스캐너 잠금 해제와 빌더 마인은 $ARCIRCLE을 직접 소각",
    "$ARCIRCLE's supply is fixed at one billion. Rewards and the burn engine run on real ecosystem income: the sources that turn the $ARCIRCLE flywheel.": "$ARCIRCLE의 공급량은 10억 개로 고정이에요. 리워드와 소각 엔진은 실제 생태계 수익, 즉 $ARCIRCLE 플라이휠을 돌리는 수익원으로 운영돼요.",
    "5% of each round's raise at the close": "라운드 마감 시 모금액의 5%",
    "See the on-chain activity the programs are designed around, and how much $ARCIRCLE a wallet has burned — read live from Arc. This is a preview, not an eligibility check: no rewards are live yet and nothing here promises any.": "프로그램 설계의 기준이 되는 온체인 활동과 지갑이 소각한 $ARCIRCLE 양을 Arc에서 실시간으로 보여줘요. 자격 확인이 아닌 미리보기예요: 아직 리워드는 없고 여기의 어떤 것도 지급을 약속하지 않아요.",
    "First CirclePad round: Round #1 raised 1,565.66 USDC and launched $ARCIA": "첫 CirclePad 라운드: 라운드 #1이 1,565.66 USDC를 모으고 $ARCIA를 런칭",
    "Burns in every utility, tracked live by source on this page": "모든 유틸리티의 소각을 이 페이지에서 출처별로 실시간 추적",
    "Treasury buybacks of $ARCIRCLE, posted with transaction links": "$ARCIRCLE 트레저리 바이백, 트랜잭션 링크와 함께 공개",
    "Publish the flywheel revenue split": "플라이휠 수익 배분 공개",
    "Phase 2 — Burn engine & rewards": "2단계 — 소각 엔진과 리워드",
    "The burn engine: the ARCIRCLE reward contract with $ARCIRCLE and $ARCIA, automatic buyback-and-burn from utility and platform revenue (timeline shared as each piece is ready)": "소각 엔진: $ARCIRCLE과 $ARCIA가 들어간 ARCIRCLE 리워드 컨트랙트, 유틸리티·플랫폼 수익으로 자동 바이백·소각 (일정은 준비되는 대로 공유)",
    "What is the burn engine?": "소각 엔진이 뭐예요?",
    "A reward contract that receives utility and platform revenue and buys back and burns $ARCIRCLE and $ARCIA automatically, so no one has to press a button. The core framework is being built; contract details, burn ratios and the rollout timeline are shared as each piece is ready.": "유틸리티·플랫폼 수익을 받아 $ARCIRCLE과 $ARCIA를 자동으로 바이백·소각하는 리워드 컨트랙트예요. 누구도 버튼을 누를 필요가 없어요. 기본 틀을 만드는 중이고, 컨트랙트 세부 사항·소각 비율·출시 일정은 준비되는 대로 공유해요.",
    "How are burns labeled by source?": "소각 출처는 어떻게 표시하나요?",
    "Each transfer to 0x…dEaD is matched to its transaction: the contract it called (burn-to-vote, Builder Mine, ARCIA DESK), or the Token Scanner unlock or secret file it paid for. Anything else is shown as a direct burn from a wallet.": "0x…dEaD로 간 각 전송을 트랜잭션과 맞춰봐요: 호출한 컨트랙트(소각 투표, 빌더 마인, ARCIA DESK) 또는 결제한 토큰 스캐너 잠금 해제·시크릿 파일. 그 외는 지갑의 직접 소각으로 표시해요.",
    "Not yet. Burns are live today in every utility; the reward contract and the holder and creator programs are being built, and they only go live once their rules are published on this page.": "아직이에요. 소각은 지금 모든 유틸리티에서 진행 중이고, 리워드 컨트랙트와 홀더·크리에이터 프로그램은 구축 중이에요. 규칙이 이 페이지에 공개된 뒤에만 시작돼요.",
    "From utilities and the community": "유틸리티와 커뮤니티",
    "From the team": "팀",
    "Each group's bars are scaled to its largest source; the % is the share of everything burned.": "각 그룹의 막대는 그룹 내 최대 출처 기준이고, %는 전체 소각량 대비 비율이에요.",
    "+ Add to wallet": "+ 지갑에 추가",
    "no withdraw function": "인출 함수 없음",
    "0% team allocation": "팀 물량 0%",
    "100% went into the pool": "100% 풀에 투입",
