    "see the score →": "점수 보기 →",
    "What it does": "쓰임새",
    "Every utility already burns $ARCIRCLE. Next, a reward contract with $ARCIRCLE and $ARCIA turns utility and platform revenue into automatic buyback-and-burn.": "모든 유틸리티가 이미 $ARCIRCLE을 소각하고 있어요. 다음은 $ARCIRCLE과 $ARCIA가 들어간 리워드 컨트랙트가 유틸리티·플랫폼 수익으로 자동 바이백·소각을 해요.",
    "See the burn engine →": "소각 엔진 보기 →",
    "What $ARCIRCLE does": "$ARCIRCLE의 쓰임새",
    "Hold it, use it, burn it.": "보유하고, 쓰고, 소각하세요.",
    "$ARCIRCLE is the key to ARCIRCLE PAD. Every use below sends $ARCIRCLE to 0x…dEaD for good, and holding it opens the rest.": "$ARCIRCLE은 ARCIRCLE PAD의 열쇠예요. 아래의 모든 사용은 $ARCIRCLE을 0x…dEaD로 영원히 보내고, 보유하면 나머지 혜택이 열려요.",
    "Hold": "보유",
    "Vote on CirclePad": "CirclePad 투표",
    "Burn-to-vote decides each round's name, ticker, logo and roadmap. One vote burns 1,000 $ARCIRCLE.": "소각 투표로 각 라운드의 이름·티커·로고·로드맵을 정해요. 1표에 1,000 $ARCIRCLE 소각.",
    "Unlock Token Scanner tools": "토큰 스캐너 도구 잠금 해제",
    "Plus and Pro tools past the free daily unlocks: 1,000 or 2,000 $ARCIRCLE burned per unlock.": "무료 일일 잠금 해제 이후 Plus·Pro 도구: 잠금 해제당 1,000 또는 2,000 $ARCIRCLE 소각.",
    "Mine on Builder Mine": "빌더 마인에서 채굴",
    "Joining a mine burns 1 USDC worth of $ARCIRCLE; pickaxes and boosts are paid in $ARCIRCLE and burned. Holding 100K / 1M / 5M adds +10 / 20 / 30% to your payouts.": "마인 참여 시 1 USDC 상당의 $ARCIRCLE이 소각되고, 곡괭이·부스트도 $ARCIRCLE로 결제 후 소각돼요. 100K / 1M / 5M 보유 시 보상 +10 / 20 / 30%.",
    "Receive Relay launches": "릴레이 런칭 받기",
    "Each CirclePad round's first buy is relayed to its contributors and to every wallet holding 100,000+ $ARCIRCLE at the snapshot.": "각 CirclePad 라운드의 첫 매수가 기여자와 스냅샷 시점에 100,000+ $ARCIRCLE을 보유한 모든 지갑에 릴레이돼요.",
    "Open ARCIA's secret file": "ARCIA 시크릿 파일 열기",
    "ARCIA's private photo file opens once per wallet for 100,000 $ARCIRCLE, burned.": "ARCIA의 비공개 사진 파일은 지갑당 한 번, 100,000 $ARCIRCLE 소각으로 열려요.",
    "Utility and platform revenue into a reward contract that buys back and burns $ARCIRCLE and $ARCIA automatically.": "유틸리티·플랫폼 수익을 리워드 컨트랙트로 보내 $ARCIRCLE과 $ARCIA를 자동으로 바이백·소각해요.",
    "burned by utilities so far": "지금까지 유틸리티가 소각",
    "time": "회",
    "times": "회",
    "That revenue goes back into $ARCIRCLE: buybacks, burns and liquidity support. The burn engine being built makes buyback-and-burn automatic, on-chain.": "그 수익은 다시 $ARCIRCLE로 돌아가요: 바이백, 소각, 유동성 지원. 구축 중인 소각 엔진이 바이백·소각을 온체인에서 자동으로 만들어요.",
    "A stronger $ARCIRCLE funds holder and creator rewards (planned) and draws in more creators — so the next round of launches is bigger.": "더 강한 $ARCIRCLE은 홀더·크리에이터 리워드(계획)를 뒷받침하고 더 많은 크리에이터를 불러와요 — 다음 런칭은 더 커져요.",
