    "Chosen by the community in Round #1 and sent to all 18 contributors. Joining the reward contract with $ARCIRCLE.": "라운드 #1에서 커뮤니티가 선택했고 18명의 기여자 모두에게 지급됐어요. $ARCIRCLE과 함께 리워드 컨트랙트에 합류 예정.",
