    "Proved Argus launches through ArcPad, fee split included. Digs Builder Mine #0. A test coin, not an investment.": "ArcPad를 통한 Argus 런칭(수수료 분배 포함)을 검증했어요. 빌더 마인 #0에서 채굴돼요. 투자가 아닌 테스트 코인이에요.",
