    "A playbook is benched when it has clearly lost money: 20+ trades averaging −1% or worse, or 10+ averaging −10% or worse. It keeps trading on paper and comes back to real money on its own when those results recover. All trades avg counts paper trades at half weight.": "전략이 뚜렷하게 손실을 내면 벤치로 빠집니다: 20건 이상 평균 −1% 이하, 또는 10건 이상 평균 −10% 이하. 벤치 중에도 페이퍼로는 계속 거래하고, 결과가 회복되면 스스로 실거래로 돌아옵니다. 전체 평균은 페이퍼 거래를 절반 가중치로 셉니다.",
