    "Her picks have done better than buying everything that passed the gates.": "ARCIA가 고른 거래가 조건을 통과한 모든 코인을 산 것보다 나았어요.",
    "Her picks haven't beaten buying everything that passed the gates yet — that's what the learning is for.": "아직은 조건을 통과한 모든 코인을 산 것보다 낫지 않아요 — 그래서 학습하고 있어요.",
