    "On-chain check": "온체인 확인",
    "Open positions are held as tokens in the same contract; their value is what an exact sell quote from the contract says right now.": "보유 중인 포지션은 같은 컨트랙트에 토큰으로 들어 있고, 가치는 지금 컨트랙트의 정확한 매도 견적 기준이에요.",
    "Open positions keep their stop-losses in the rules, but nothing is checked until it runs again. The team has been alerted.": "규칙상 손절선은 그대로지만, 다시 실행될 때까지는 확인되지 않아요. 팀에 알림이 갔어요.",
    "Overview": "개요",
