    "Why she bought": "매수 이유",
    "Win rate": "승률",
    "Wins": "수익",
    "\"since\" is the price now against the price when she passed. Dodged: down 30%+ since. Missed run: up 100%+ since.": "\"since\"는 거절했을 때 가격 대비 현재 가격이에요. 피함: 이후 30% 이상 하락. 놓친 급등: 이후 100% 이상 상승.",
    "after the first profitable day": "첫 수익일 이후",
    "and what happened next": "그리고 그 뒤",
    "counted from the next trade": "다음 거래부터 집계",
    "dodged": "피함",
    "due at the next daily run": "다음 일일 실행 때 소각",
    "from her last run": "마지막 실행 기준",
    "gross wins ÷ gross losses": "총수익 ÷ 총손실",
