    "This wallet holds": "이 지갑 잔액:",
    "The desk picks it up on its next run.": "데스크가 다음 실행 때 반영해요.",
    "The transfer didn't go through.": "전송이 완료되지 않았어요.",
    "Desk money": "데스크 자금",
    "USDC in the contract": "컨트랙트 USDC",
    "USDC to take out": "출금할 USDC",
    "From this wallet to the desk contract, as a USDC token transfer.": "이 지갑에서 데스크 컨트랙트로 USDC 토큰 전송.",
    "From the desk contract to the owner wallet — any amount, any time, paused or not.": "데스크 컨트랙트에서 owner 지갑으로 — 금액·시간 제한 없이, 멈춤 여부와 상관없이.",
    "position is open — its coins aren't USDC yet. Pause first and wait for it to close to take everything out.": "개 포지션이 열려 있어요 — 그 코인은 아직 USDC가 아니에요. 전부 빼려면 먼저 멈추고 포지션이 닫힐 때까지 기다리세요.",
    "positions are open — their coins aren't USDC yet. Pause first and wait for them to close to take everything out.": "개 포지션이 열려 있어요 — 그 코인들은 아직 USDC가 아니에요. 전부 빼려면 먼저 멈추고 포지션이 닫힐 때까지 기다리세요.",
    "Paused — no new buys": "멈춤 — 새 매수 없음",
