    "Pausing stops new buys only; she still sells what she holds.": "멈추면 새 매수만 막혀요. 보유한 코인은 계속 팔아요.",
    "The desk records deposits and withdrawals on its next run (about a minute). Neither counts as profit or loss.": "데스크는 다음 실행(약 1분) 때 입출금을 기록해요. 수익이나 손실로 계산하지 않아요.",
