    "Limits removed: a buy is now 6% of the desk with no cap, and there's no daily limit.": "한도를 해제했어요: 이제 매수는 데스크의 6%이고 상한이 없으며, 하루 한도도 없어요.",
    "Closed for now": "지금은 닫힘",
