    "My recent trades lost more than they made — minimum size while I learn.": "최근 거래가 번 것보다 잃은 게 많아요 — 배우는 동안 최소 크기로 갈게요.",
    "My recent trades are slightly down — half size until they recover.": "최근 거래가 약간 손실이에요 — 회복될 때까지 절반 크기로 갈게요.",
