    "The last 80 closed trades. A high win rate can still lose money if the losses are bigger than the wins — this shows it in dollars.": "최근 종료된 80건의 거래입니다. 승률이 높아도 손실이 이익보다 크면 돈을 잃을 수 있어요 — 여기서는 달러로 보여줍니다.",
    "recent pump scalps (real and paper), replayed with a plain take-profit and stop-loss, no runner.": "건의 최근 급등 스캘핑(실거래와 모의)를 러너 없이 단순 익절·손절로 다시 계산했습니다.",
