    "(the pump scalp:": "(급등 스캘핑:",
    "of the desk if the coin falls back to its launch floor — the closer the floor, the bigger the buy can be": "(데스크 대비) — 코인이 런칭 바닥가로 돌아갈 경우. 바닥가가 가까울수록 더 크게 살 수 있어요",
    "Half size after 3 losses in a row, when the last 20 real trades lost money in dollars, or once the day is down 5%; the minimum size when they lost twice what they made": "3연속 손실 후, 최근 실거래 20건이 달러 기준 손실일 때, 또는 하루 -5% 이후에는 절반 크기. 잃은 금액이 번 금액의 두 배면 최소 크기",
    "A pump scalp down": "급등 스캘핑가 매수 후",
    "A buy's size comes from the settings below (at least $3); these only cap it. They are also the most the trading key could spend in a day if it ever leaked — with no limit, the whole desk.": "매수 크기는 아래 설정에서 정해지고(최소 $3), 이 한도는 상한만 둡니다. 거래 키가 유출됐을 때 하루에 쓸 수 있는 최대치이기도 해요 — 한도가 없으면 데스크 전체.",
    "Sizing and pump scalp settings": "크기 및 급등 스캘핑 설정",
    "Most a buy may lose at the launch floor": "런칭 바닥가에서 매수 한 번의 최대 손실",
    "Pump scalp: at most": "급등 스캘핑: 최대",
    "Pump scalp: top-10 dump under": "급등 스캘핑: 상위 10 매도 시 하락 미만",
    "Early exit: down": "조기 청산: 하락",
    "Sign and save": "서명하고 저장",
    "Back to defaults": "기본값으로",
    "Signed by the owner wallet (no gas). They change how much a buy spends and which pump scalps pass — they can't make her trade. Used from her next run.": "오너 지갑으로 서명합니다(가스 없음). 매수 크기와 통과할 급등 스캘핑만 바꾸며, 거래를 시킬 수는 없어요. 다음 실행부터 적용됩니다.",
    "Daily post draft": "일일 게시글 초안",
    "Copied.": "복사했어요.",
    "Real numbers from the desk right now. Edit before posting.": "지금 데스크의 실제 숫자입니다. 게시 전에 수정하세요.",
    "Starts once the desk is funded.": "데스크에 자금이 들어오면 시작됩니다.",
    "last saved": "마지막 저장",
    "defaults": "기본값",
    "Couldn't save — try again.": "저장하지 못했어요 — 다시 시도하세요.",
    "Saved. She uses them from her next run.": "저장했어요. 다음 실행부터 적용됩니다.",
    "Limits removed: a buy is sized by the desk's settings with no cap, and there's no daily limit.": "한도 해제: 매수 크기는 데스크 설정대로, 상한과 일일 한도 없음.",
    "Early exit (fell right after the buy)": "조기 청산(매수 직후 하락)",
    "At the pump scalp's floor limit": "급등 스캘핑 바닥가 한도에서",
    "a buy of at most": "매수는 최대",
    "current exits": "현재 청산값",
    "best in the grid": "표에서 최고",
    "minutes after the buy is sold at once": "분 안에 이만큼 떨어지면 바로 팝니다",
    "default value": "기본값",
    "due now": "지금 예정",
    "open positions": "개 보유 포지션",
    "of the desk per buy": "(매수당, 데스크 대비)",
    "Early exit: in the first": "조기 청산: 매수 후 처음",
    "Real money has stricter rules than paper. An Argus pool starts at its launch price, and if the early buyers all sell, the price falls back there in one block. So a real buy needs the price at most 6× its launch floor (the pump scalp: 7×), a top-10 sell-off that would drop it less than 80% (the pump scalp: 60%), and no critical flag in the last 6 hours.": "실제 자금에는 모의보다 엄격한 규칙이 적용됩니다. Argus 풀은 런칭 가격에서 시작하고, 초기 매수자가 모두 팔면 한 블록 만에 그 가격으로 돌아갑니다. 그래서 실제 매수는 가격이 런칭 바닥가의 6배 이하(급등 스캘핑은 7배), 상위 10개 지갑이 다 팔 때 하락폭 80% 미만(급등 스캘핑은 60%), 최근 6시간 동안 치명 플래그 없음이 필요합니다.",
    "A buy starts at 6% of the desk (at least $3) and is sized by risk: if the coin fell back to its launch floor, it would lose at most 1.25% of the desk. Size halves after 3 real losses in a row, when the last 20 real trades lost money in dollars, or once the day is down 5%, and drops to the $3 minimum when those trades lost twice what they made. A pump scalp that falls 5% within 2 minutes of the buy is sold at once. The desk's owner can tune these within fixed bounds by signing with the owner wallet; the settings can't make her trade.": "매수는 데스크 자금의 6%(최소 $3)에서 시작해 리스크에 맞춰 정해집니다: 코인이 런칭 바닥가로 돌아가도 데스크의 1.25% 이상 잃지 않도록요. 3연속 실거래 손실 후, 최근 실거래 20건이 달러 기준 손실일 때, 또는 하루 -5%가 되면 크기가 절반이 되고, 그 거래들이 번 것의 두 배를 잃었다면 최소 $3로 내려갑니다. 매수 후 2분 안에 5% 떨어진 급등 스캘핑은 바로 팝니다. 데스크 오너는 오너 지갑 서명으로 정해진 범위 안에서 이 값을 조정할 수 있고, 설정으로 거래를 시킬 수는 없습니다.",
    "At most 10 positions open and 8 buys an hour; $2 always stays in cash; the contract's own limits cap each buy and each day. During the warm-up (the first 25 real trades): $3 a trade and at most 6 buys an hour. Each DCA tranche is $2. Since 30 Sep 2026 real money goes only through the Pump scalp; the other playbooks keep trading on paper so the desk keeps learning from them.": "동시 포지션 최대 10개, 시간당 매수 최대 8회; 항상 $2는 현금으로 유지; 컨트랙트 자체 한도가 매수당·하루 금액을 제한합니다. 워밍업(처음 25건의 실제 거래) 동안은 거래당 $3, 시간당 최대 6회. 물타기 매수는 각 $2. 2026년 9월 30일부터 실제 자금은 급등 스캘핑으로만 거래하며, 나머지 플레이북은 모의로만 계속 거래해서 데스크가 계속 배워요.",
    "A call is about risk over the next 24 hours, never about price direction — not a signal to buy or sell.": "콜은 앞으로 24시간의 위험에 대한 판단이지 가격 방향이 아닙니다 — 매수·매도 신호가 아니에요.",
    "ARCIA off": "ARCIA 꺼짐",
