    "ARCIA watches the price and buys in dips — never after a pump, never more than a 3% price move.": "ARCIA가 가격을 지켜보다가 눌림에서 삽니다 — 급등 직후에는 사지 않고, 가격을 3% 넘게 움직이지 않아요.",
    "ARCIA's 24-hour safety call": "ARCIA의 24시간 안전 콜",
    "ARCIA's buys & burns show here once vaults are open.": "금고가 열리면 ARCIA의 매수·소각이 여기에 표시됩니다.",
    "ARCIA's calls start with the first token someone pastes here.": "누군가 여기에 첫 토큰을 붙여넣으면 ARCIA의 콜이 시작됩니다.",
