    "Order cancelled.": "주문이 취소됐어요.",
    "Order placed — it fills as soon as a wallet or the pool meets your price.": "주문 완료 — 다른 지갑이나 풀이 내 가격에 닿는 즉시 체결돼요.",
    "Orders below the ask and above the bid fill from the pool as soon as its price gets there.": "매도 호가 아래·매수 호가 위의 주문은 풀 가격이 닿는 즉시 풀에서 체결돼요.",
    "Pick a market above — any Arc token with a Uniswap v4 pool (Argus, ArcPad or a plain pool).": "위에서 마켓을 고르세요 — Uniswap v4 풀이 있는 Arc 토큰이면 모두 돼요 (Argus, ArcPad 또는 일반 풀).",
    "Placing…": "주문하는 중…",
    "Pool price": "풀 가격",
    "Preview — ARCIRCLE Orders opens once its contract is live on Arc": "미리보기 — ARCIRCLE Orders는 Arc에 컨트랙트가 배포되면 열려요",
