    "Each part": "회당",
    "Editing an order — placing this one cancels the old one.": "주문 수정 중 — 이 주문을 넣으면 기존 주문은 취소돼요.",
    "Enter a stop-loss price.": "손절 가격을 입력해 주세요.",
    "Enter a take-profit price.": "익절 가격을 입력해 주세요.",
    "Enter the least you'd sell for per token.": "토큰당 최저 매도 가격을 입력해 주세요.",
    "Enter the lowest price you'd sell at.": "최저 매도 가격을 입력해 주세요.",
    "Enter the most you'd pay per token.": "토큰당 최대 매수 가격을 입력해 주세요.",
