    "above your price (pool fee and token tax). Wallet-to-wallet matches don't pay them.": "내 가격보다 높아야 해요 (풀 수수료와 토큰 세금). 지갑 간 체결은 이 비용이 없어요.",
    "Fills now (taker)": "즉시 체결 (테이커)",
    "Fills orders every minute": "1분마다 주문을 체결해요",
