    "Never sell below": "최저 매도 가격",
    "No markets with orders yet — open any Arc token above and place the first one.": "아직 주문이 있는 마켓이 없어요 — 위에서 Arc 토큰을 열고 첫 주문을 걸어 보세요.",
    "No trades in this pool in the last 3 days.": "최근 3일간 이 풀에 거래가 없어요.",
