    "A new week has started": "새로운 주가 시작됐어요",
    "Add it to your lock": "락업에 추가",
    "An ARCIRCLE Predict market": "ARCIRCLE Predict 마켓 개설",
    "Approve the $ARCIRCLE": "$ARCIRCLE 승인",
    "Approve the USDC for ARCIRCLE Orders": "ARCIRCLE Orders에 USDC 승인",
