    "thin": "얕음",
    "No pools to show here yet.": "아직 표시할 풀이 없어요.",
    "24h fees = 24h volume × the pool's LP fee. Fee APR is that, for a year, over the pool's liquidity — a rough guide: volume moves every day, and pools under $1K of liquidity are marked thin.": "24시간 수수료 = 24시간 거래량 × 풀의 LP 수수료. 수수료 APR은 이를 1년으로 환산해 풀 유동성으로 나눈 값이에요 — 대략적인 기준일 뿐, 거래량은 매일 바뀌고 유동성 $1K 미만 풀은 얕음으로 표시돼요.",
    "A new Uniswap v4 pool on Robinhood Chain, with no hook. You set its first price and make the first deposit.": "훅 없는 새 Uniswap v4 풀을 Robinhood Chain에 만들어요. 첫 가격과 첫 예치는 직접 정해요.",
    "enter the price in ETH": "가격은 ETH로 입력하세요",
    "That address isn't a token on this chain.": "이 주소는 이 체인의 토큰이 아니에요.",
    "Uses Uniswap's own PositionManager on Robinhood Chain. If the price moves more than the limit above before your transaction lands, it's cancelled and nothing is spent.": "Robinhood Chain의 Uniswap 공식 PositionManager를 사용해요. 거래가 처리되기 전에 가격이 위 한도보다 많이 움직이면 취소되고 아무것도 쓰이지 않아요.",
    "Two coins": "코인 두 개",
