    "Bid-ask": "비드-애스크",
    "Your coins sit above today's price and sell into the market bit by bit as the price climbs — earning fees on the way up.": "코인이 현재 가격 위에 놓여 가격이 오를수록 조금씩 시장에 팔려요 — 오르는 동안 수수료를 벌어요.",
    "Your coins sit below today's price and buy the token bit by bit as the price falls — earning fees on the way down.": "코인이 현재 가격 아래에 놓여 가격이 내릴수록 조금씩 토큰을 사요 — 내리는 동안 수수료를 벌어요.",
    "The range is too narrow for this pool's tick spacing.": "이 풀의 틱 간격에 비해 범위가 너무 좁아요.",
    "positions in one transaction": "개 포지션을 한 번의 트랜잭션으로",
    "Liquidity added — your positions are below.": "유동성 추가 완료 — 포지션은 아래에 있어요.",
    "Fees to collect": "수령할 수수료",
    "This pool runs its launchpad's hook. The hook may turn away liquidity added from outside — if it does, your wallet shows the error before anything is spent.": "이 풀은 런치패드의 훅으로 운영돼요. 훅이 외부에서 추가하는 유동성을 거절할 수 있어요 — 그러면 아무것도 쓰이기 전에 지갑에 오류가 표시돼요.",
    "A graduated Pons coin's pool — its launch liquidity sits in the Pons locker for good.": "졸업한 Pons 코인의 풀 — 런칭 유동성은 Pons 락커에 영구히 묶여 있어요.",
    "Finding your positions on Robinhood Chain…": "Robinhood Chain에서 내 포지션을 찾는 중…",
    "Robinhood Chain's PositionManager didn't answer as expected — writes are paused here. Try again later.": "Robinhood Chain의 PositionManager가 예상대로 응답하지 않아 거래를 잠시 멈췄어요. 나중에 다시 시도하세요.",
    "The first look at a token reads every position on Robinhood Chain — later visits are instant.": "토큰을 처음 볼 때는 Robinhood Chain의 모든 포지션을 읽어요 — 다음부터는 바로 열려요.",
    "Find the pools worth providing to on Arc and Robinhood Chain, then every Uniswap v4 pool a token trades in — price, depth, every LP position and how much of it is locked. Add liquidity with two coins or just one, in a shape, and see what your positions are worth and earn.": "Arc와 Robinhood Chain에서 유동성을 공급할 만한 풀을 찾고, 토큰이 거래되는 모든 Uniswap v4 풀의 가격·깊이·모든 LP 포지션과 잠긴 비율을 확인하세요. 코인 두 개 또는 하나로 모양을 정해 유동성을 추가하고, 내 포지션의 가치와 수익을 확인하세요.",
    "Today's price": "현재 가격",
    "the dashed line": "점선",
    "$ARCIA is CirclePad Round #1's coin, named after ARCIA and chosen by the community. It joins $ARCIRCLE in the reward contract's automated buyback-and-burn. Its contract on Arc:": "$ARCIA는 CirclePad 라운드 #1의 코인으로, ARCIA의 이름을 따 커뮤니티가 선택했어요. 리워드 컨트랙트의 자동 바이백·소각에 $ARCIRCLE과 함께 참여해요. Arc 컨트랙트:",
