    "New in v2": "v2 새 기능",
    "On a phone, UP and DOWN stay pinned to the bottom of the screen with the quick amounts, so you can bet without scrolling.": "휴대폰에서는 UP과 DOWN 버튼이 빠른 금액과 함께 화면 아래에 고정돼서, 스크롤 없이 베팅할 수 있어요.",
    "Before you bet, the box shows what your amount would pay if UP wins and if DOWN wins (if nobody else bets after you), and warns when it's under the smallest or over the largest bet.": "베팅 전에 내 금액이 UP이 이길 때와 DOWN이 이길 때 얼마를 받는지(이후 아무도 베팅하지 않는다면) 보여주고, 최소보다 적거나 최대보다 많으면 알려줘요.",
    "Each round finishes with a 3-2-1 countdown, then \"Reading the pool…\" until the result lands; the winning side lights up.": "라운드는 3-2-1 카운트다운으로 끝나고, 결과가 나올 때까지 \"풀 가격 읽는 중…\"이 보여요. 이긴 쪽이 빛나요.",
    "Market chips show the time left to bet, the pot and a small line of recent prices; a chip pulses in its last 30 seconds.": "마켓 칩에는 베팅 마감까지 남은 시간, 팟, 최근 가격 미니 차트가 보이고, 마지막 30초에는 칩이 깜빡여요.",
    "ARCIA calls every round (UP if the coin is above its price to beat, DOWN if below) before bets close, and her record is kept next to \"the crowd\" (the side with more money). It's for fun, not advice.": "ARCIA가 매 라운드를 베팅 마감 전에 예측하고(가격이 기준 가격보다 높으면 UP, 낮으면 DOWN), 그 전적을 \"군중\"(돈이 더 많이 몰린 쪽)과 함께 기록해요. 재미용이지 투자 조언이 아니에요.",
    "The last 10 results sit under the token's name, with a dot where ARCIA's call was scored. Reactions (hot, to the moon, cold, watching) can be left on the live round.": "토큰 이름 아래에 최근 10라운드 결과가 보이고, ARCIA의 예측이 채점된 곳에 점이 찍혀요. 진행 중인 라운드에 반응(뜨거움, 투더문, 차가움, 지켜보는 중)을 남길 수 있어요.",
    "The bell on a market reminds you 30 seconds before bets close, every round, in this browser. Badges come with your first call, first win, streaks of 3, 5 and 10, and 10, 50 and 100 rounds.": "마켓의 종 버튼을 누르면 이 브라우저에서 매 라운드 베팅 마감 30초 전에 알려줘요. 첫 예측, 첫 승리, 3·5·10연승, 10·50·100라운드에 배지를 받아요.",
    "All markets lets you bet straight from a tile with your amount. The weekly leaderboard is a season that resets every Monday 00:00 UTC. In Telegram, /predict lists the live rounds.": "All markets에서 내 금액으로 타일에서 바로 베팅할 수 있어요. 주간 리더보드는 매주 월요일 00:00 UTC에 초기화되는 시즌이에요. 텔레그램에서 /predict로 진행 중인 라운드를 볼 수 있어요.",
    "before the end": "종료 전",
