    "A take-profit above and a stop-loss below on the same tokens: when one fills, the other is cancelled on-chain.": "같은 토큰에 위로는 익절, 아래로는 손절을 걸어요. 하나가 체결되면 다른 하나는 온체인에서 취소돼요.",
    "A take-profit and stop-loss wait for this buy to fill": "이 매수가 체결되면 익절·손절이 이어서 걸려요",
