    "It's already in your wallet on Robinhood Chain — the same address that holds your $ARCIRCLE on Arc.": "이미 Robinhood Chain 지갑에 들어 있어요 — Arc에서 $ARCIRCLE을 보유한 바로 그 주소예요.",
