    "Your lock already runs longer than that — pick at least as many days as are left.": "락이 이미 그보다 길어요 — 남은 일수 이상을 고르세요.",
    "Your lock has ended: withdrawing is free.": "락이 끝났어요: 무료로 출금할 수 있어요.",
