    "streams out over 20 days": "20일에 걸쳐 지급",
    "time left ÷ the lock's length": "남은 기간 ÷ 락 기간",
    "Holding $ARCIRCLE multiplies your reward weight. Counted on Arc (wallet + ARCIRCLE Staking) and Robinhood Chain; a boost lasts 7 days.": "$ARCIRCLE을 보유하면 보상 가중치가 커져요. Arc(지갑 + ARCIRCLE Staking)와 Robinhood Chain 보유량을 합산하고, 부스트는 7일간 유지돼요.",
    "Staking is free. Estimates use today's rewards and stakers; they change as those do. Not financial advice.": "스테이킹은 무료예요. 예상치는 오늘의 보상과 스테이커 기준이며 변동돼요. 투자 조언이 아닙니다.",
    "Adding or renewing restarts your lock from now; it can't end earlier than it does now": "추가하거나 연장하면 지금부터 락이 다시 시작되고, 지금보다 일찍 끝날 수는 없어요",
    "veARCIA isn't deployed yet": "veARCIA가 아직 배포되지 않았어요",
    "boost signing isn't switched on yet": "부스트 서명이 아직 켜지지 않았어요",
    "couldn't read every chain — try again in a moment": "모든 체인을 읽지 못했어요 — 잠시 후 다시 시도하세요",
    "Stake $ARCIA 1–20 days, earn $ARCIA — $ARCIRCLE boosts it": "$ARCIA를 1–20일 스테이킹하고 $ARCIA 보상 — $ARCIRCLE로 부스트",
    "Utility · stake $ARCIA on Robinhood Chain": "유틸리티 · Robinhood Chain에서 $ARCIA 스테이킹",
    "$ARCIA rewards · on-chain": "$ARCIA 보상 · 온체인",
    "Stake $ARCIA for 1 to 20 days and it becomes veARCIA. Rewards in $ARCIA stream to stakers every second, longer locks earn up to 2x, and holding $ARCIRCLE adds up to 2x more. veARCIA is also how you'll take part in the ARCIA AI ecosystem and its governance.": "$ARCIA를 1~20일 스테이킹하면 veARCIA가 됩니다. $ARCIA 보상이 매초 스테이커에게 흘러가고, 길게 잠글수록 최대 2배, $ARCIRCLE을 보유하면 최대 2배가 더해져요. veARCIA는 앞으로 ARCIA AI 생태계와 거버넌스에 참여하는 수단이기도 해요.",
    "veARCIA guide": "veARCIA 가이드",
    "What is veARCIA?": "veARCIA란?",
    "Locks and withdrawing": "락과 출금",
    "The $ARCIRCLE boost": "$ARCIRCLE 부스트",
    "Add your $ARCIA rewards to your stake — same lock, no tokens move": "$ARCIA 보상을 스테이킹에 더해요 — 락 그대로, 토큰 이동 없음",
    "Approve once — no approval step next time": "한 번만 승인 — 다음엔 승인 단계 없음",
    "Auto-renew": "자동 연장",
    "Auto-renew is off — the countdown has started.": "자동 연장을 껐어요 — 카운트다운이 시작됐어요.",
    "Auto-renew is on": "자동 연장 켜짐",
    "Auto-renew is on.": "자동 연장을 켰어요.",
    "Auto-renew is on: pick at least your current length.": "자동 연장 중이에요: 현재 기간 이상을 고르세요.",
    "Compound": "복리",
    "Compounded": "복리 적립",
    "Compounded — your rewards are staked.": "복리 완료 — 보상이 스테이킹에 더해졌어요.",
    "Daily rewards over time": "일일 보상 추이",
    "Get $ARCIA": "$ARCIA 구하기",
    "Keep the lock (and its multiplier) running until you turn it off.": "끌 때까지 락(과 배율)을 계속 유지해요.",
    "My veARCIA": "내 veARCIA",
    "Next 20 days": "앞으로 20일",
    "Notify me when it opens": "오픈하면 알려주세요",
    "On — your multiplier never runs out. Turning it off starts the full countdown.": "켜짐 — 배율이 끝나지 않아요. 끄면 전체 기간 카운트다운이 시작돼요.",
    "Opens soon.": "곧 오픈해요.",
    "Received so far": "지금까지 받은 양",
    "Runway": "남은 지급 기간",
    "Stake $ARCIA on Robinhood Chain for 1–20 days.": "Robinhood Chain에서 $ARCIA를 1–20일 스테이킹하세요.",
    "Stake some $ARCIA first.": "먼저 $ARCIA를 스테이킹하세요.",
    "The daily rewards show here as they change.": "일일 보상이 바뀌면 여기에 표시돼요.",
    "The first stakers show here.": "첫 스테이커들이 여기에 표시돼요.",
