    "Sent — Circle mints it on Arc in a few minutes.": "보냈어요 — 몇 분 안에 Circle이 Arc에서 발행해요.",
    "Stop watching (the transfer still completes)": "확인 그만하기 (전송은 그대로 완료돼요)",
