    "That's less than the fee.": "수수료보다 적어요.",
    "This page checks every few seconds. You can close it — the transfer finishes on its own and shows here when you come back.": "이 페이지가 몇 초마다 확인해요. 닫아도 괜찮아요 — 전송은 알아서 끝나고 다시 오면 여기 보여요.",
    "Where your USDC goes": "내 USDC가 가는 길",
    "Your USDC is on Arc.": "USDC가 Arc에 도착했어요.",
    "fast: usually a few minutes": "빠른 전송: 보통 몇 분",
    "standard: up to about 20 minutes": "일반 전송: 최대 약 20분",
    "You rejected the request in your wallet.": "지갑에서 요청을 거절했어요.",
    "Earlier rounds": "지난 라운드",
    "Book": "호가",
    "opens when it graduates": "졸업하면 열림",
