    "On its Pons bonding curve": "Pons 본딩 커브 진행 중",
    "Its Uniswap v4 pool opens when it graduates. Place a limit buy now — it waits, and fills from the new pool at your price or better.": "졸업하면 Uniswap v4 풀이 열려요. 지금 지정가 매수를 걸어 두면 기다렸다가, 새 풀에서 내 가격 이하로 체결돼요.",
    "Limit buys only until it graduates — the pool's first price can be far from the curve's. Set the most you'd pay.": "졸업 전에는 지정가 매수만 가능해요 — 풀의 첫 가격은 커브 가격과 크게 다를 수 있어요. 낼 수 있는 최고가를 정하세요.",
    "Trigger at market cap": "트리거 시가총액",
    "At market cap": "목표 시가총액",
    "Enter a price per token": "토큰당 가격으로 입력",
    "Enter a market cap in dollars": "시가총액(달러)으로 입력",
    "That moves the price a lot. Split it into 12 parts over 6 hours instead?": "가격을 크게 움직여요. 대신 6시간 동안 12번에 나눠 살까요?",
    "Use Timed (DCA)": "분할(DCA)로 바꾸기",
    "5-minute candles of the last 24 hours that traded through this price": "지난 24시간 동안 이 가격을 거쳐 간 5분봉 수",
    "Switched to Timed (DCA)": "분할(DCA)로 바꿨어요",
    "12 parts over 6 hours — change it below.": "6시간 동안 12번 — 아래에서 바꿀 수 있어요.",
    "Its pool opens when it graduates — the depth chart starts then.": "졸업하면 풀이 열려요 — 깊이 차트는 그때부터 보여요.",
    "From the pool's active liquidity, held constant over ±10% — approximate past its current range": "풀의 활성 유동성을 ±10% 구간에서 그대로 가정한 값 — 현재 범위 밖은 근사치예요",
    "Pool, ±10% (approx.)": "풀, ±10% (근사)",
    "Its pool opens when it graduates from the Pons curve — the chart starts with its first trade.": "Pons 커브를 졸업하면 풀이 열려요 — 차트는 첫 거래부터 시작해요.",
    "Cancel on-chain": "온체인 취소",
    "More actions": "더 보기",
    "waits for its pool — it opens when the token graduates from Pons": "풀을 기다리는 중 — 토큰이 Pons를 졸업하면 열려요",
    "Limit buys placed now wait here for the pool to open.": "지금 건 지정가 매수는 풀이 열릴 때까지 여기서 기다려요.",
    "price · 24h · your orders · nearest": "가격 · 24시간 · 내 주문 · 가장 가까운 주문",
    "last seen here": "여기서 마지막으로 본 가격",
    "open order": "미체결 주문",
    "open orders": "미체결 주문",
    "no orders": "주문 없음",
    "No pool price yet for a % price.": "% 가격을 쓸 풀 가격이 아직 없어요.",
    "That market cap isn't a number.": "시가총액이 숫자가 아니에요.",
    "No market cap for this token yet.": "이 토큰의 시가총액을 아직 알 수 없어요.",
