    "Alerts with the tab closed: the ARCIA bot on Telegram, /orderalerts on.": "탭을 닫은 채 알림 받기: 텔레그램 ARCIA 봇에서 /orderalerts on.",
    "Safety and fees": "안전과 수수료",
    "Tell ARCIA your order — she fills ARCIRCLE Orders for you": "ARCIA에게 주문을 말하세요 — ARCIRCLE Orders를 대신 채워 드려요",
    "Type it in the chat, like the lines below. She opens ARCIRCLE Orders with it filled in; you check it and sign. Nothing is placed before that.": "채팅에 아래처럼 적으면 ARCIRCLE Orders가 채워진 채로 열려요. 확인하고 서명하는 건 본인이에요. 그 전에는 아무 주문도 들어가지 않아요.",
    "Try it": "해보기",
    "Talk": "대화",
