    "An AI character, automated and run by the ARCIRCLE team. More of her official profile is on the way.": "ARCIRCLE 팀이 자동화해 운영하는 AI 캐릭터예요. 공식 프로필은 곧 더 공개돼요.",
    "Version 4 — new features are added regularly": "버전 4 — 새 기능이 꾸준히 추가돼요",
    "More from ARCIA": "ARCIA 더 보기",
