    "A signature, no gas. The keeper stops it then — the round open for bets still runs and settles.": "서명만 하면 돼요(가스 없음). 그때 키퍼가 마켓을 멈추고, 베팅이 열려 있던 라운드는 끝까지 진행·정산돼요.",
